//! The display profiles: for each, the display, the font vtium draws on it,
//! the grid that gives, and how the card's blocks are arrayed on it.

use vtium_render::Depth;

use crate::card::{BLOCK_COLS, BLOCK_ROWS, BLOCKS};

/// What a profile draws its text with.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Glyphs {
    /// A set built into vtium (ADR-1200 D7), drawn at `height` pixels.
    Builtin { set: &'static str, height: u32 },
    /// The desktop frit, `frits/desktop.vtfrit`, its glyphs generated by
    /// vtium-config's engine from the pinned outline fonts of
    /// [`crate::fonts`] in the profile's cell, `height` pixels high.
    Desktop { height: u32 },
    /// The shipped frit `tiny5`, `crates/vtium-config/frits/tiny5.vtfrit`,
    /// its glyphs generated by vtium-config's engine from Tiny5 Mono's
    /// pinned BDF file ([`crate::fonts`]) at its own cell, `height` pixels
    /// high.
    Tiny5 { height: u32 },
}

impl Glyphs {
    /// The set's name, as `font-name` and the card's header give it.
    pub fn set(self) -> &'static str {
        match self {
            Glyphs::Builtin { set, .. } => set,
            Glyphs::Desktop { .. } => "desktop",
            Glyphs::Tiny5 { .. } => "tiny5",
        }
    }

    /// The cell height asked of the set.
    pub fn height(self) -> u32 {
        match self {
            Glyphs::Builtin { height, .. }
            | Glyphs::Desktop { height }
            | Glyphs::Tiny5 { height } => height,
        }
    }
}

/// One display profile.
#[derive(Clone, Copy, Debug)]
pub struct Profile {
    /// Its directory under `docs/specimens/`.
    pub name: &'static str,
    pub width: u32,
    pub height: u32,
    /// The display's depth, as the card's header names it.
    pub depth: &'static str,
    /// The display class it falls in, by the display-capabilities record's
    /// table (vtium/vtium#136).
    pub class: &'static str,
    /// How vtium-render draws it: `display-depth`.
    pub display: Depth,
    pub glyphs: Glyphs,
    /// The cell the set draws at that height, which the drawing must give.
    pub cell: (u32, u32),
    /// What it is, one line, for the tables.
    pub summary: &'static str,
    /// Why this font and size is the best choice on this display.
    pub why: &'static str,
    /// The vtium.conf lines for the profile, comments included.
    pub conf: &'static str,
    /// For a gray panel, the conversion its driver applies to vtium's color
    /// drawing, which the profile's renders simulate.
    pub panel: Option<Panel>,
    /// The screens vtium's message bars take after the card: one, or two
    /// where the four notices fill a screen of their own
    /// ([`crate::bars`]).
    pub bar_screens: usize,
}

/// An XRGB8888 pixel's gray8, BT.601 luma in the kernel's integers:
/// `(77r + 150g + 29b) / 256` (Linux v7.3,
/// `drivers/gpu/drm/drm_format_internal.h:39-47`).
pub fn gray8(rgb: [u8; 3]) -> u8 {
    let [r, g, b] = rgb.map(u32::from);
    ((77 * r + 150 * g + 29 * b) / 256) as u8
}

/// A gray panel's conversion, as its Linux driver makes it from the
/// XRGB8888 framebuffer vtium draws (Linux v7.3). Each pixel goes to gray8
/// by BT.601 luma, `(77r + 150g + 29b) / 256`
/// (`drivers/gpu/drm/drm_format_internal.h:39-47`, through
/// `drm_fb_xrgb8888_to_gray8`, `drivers/gpu/drm/drm_format_helper.c:1084-1126`),
/// then to the panel's levels by the gray8 value's top bits.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Panel {
    /// st7586's 4 levels: gray8 shifted right 6, then its lookup table
    /// (`drivers/gpu/drm/sitronix/st7586.c:80-106`).
    St7586,
    /// The SSD132x panels' 16 levels: gray8's top nibble, two pixels a byte
    /// (`drivers/gpu/drm/solomon/ssd130x.c:968` and `:801-809`).
    Ssd132x,
}

impl Panel {
    /// The bits of gray8 the panel keeps.
    pub fn bits(self) -> u32 {
        match self {
            Panel::St7586 => 2,
            Panel::Ssd132x => 4,
        }
    }

    /// The driver's name and source, for the READMEs.
    pub fn driver(self) -> &'static str {
        match self {
            Panel::St7586 => {
                "st7586 (`drivers/gpu/drm/sitronix/st7586.c:80-106`: gray8 >> 6, its 4 levels through `st7586_lookup`)"
            }
            Panel::Ssd132x => {
                "ssd130x's SSD132x path (`drivers/gpu/drm/solomon/ssd130x.c:968` and `:801-809`: gray8 >> 4, two 4-bit pixels a byte)"
            }
        }
    }

    /// `rgb`, one pixel, as the panel shows it: its level drawn as the gray
    /// that level is on a panel whose levels are evenly spaced.
    pub fn show(self, rgb: [u8; 3]) -> u8 {
        let level = u32::from(gray8(rgb)) >> (8 - self.bits());
        let top = (1 << self.bits()) - 1;
        (level * 255 / top) as u8
    }
}

/// How a profile's grid holds the card: the blocks a page holds across and
/// down, where the first sits, and the pages the card takes.
///
/// A grid shorter than a block's 30 rows, as a 6x9 cell gives 26 at
/// 320x240, shows each block in slices: the first slice is the block's
/// rows from the top that fit, and each later slice repeats the block's
/// title row and then shows the next rows that fit below it. Every row of
/// the block is shown once, but the title, which every slice shows. Pages
/// take the slices in the card's order, as many side by side as the
/// grid's width holds blocks, one row of them a page; a grid 53 columns
/// wide holds one.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Layout {
    pub cols: usize,
    pub rows: usize,
    pub across: usize,
    pub down: usize,
    /// The first block's top row and left column: the blocks are centered.
    pub top: usize,
    pub left: usize,
    pub pages: usize,
    /// The screens each block takes: 1 on a grid at least a block high.
    pub slices: usize,
}

/// A block, or a slice of it, as a page places it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Placed {
    /// The block, from 0.
    pub block: usize,
    /// The slice of the block, from 0; always 0 on a grid a block high.
    pub slice: usize,
    /// The grid's row and column the slice's top left sits at.
    pub top: usize,
    pub left: usize,
}

impl Layout {
    /// The layout of a grid `cols` by `rows`; `None` for a grid narrower
    /// than one block, or too short to show its title and one more row.
    pub fn new(cols: usize, rows: usize) -> Option<Layout> {
        let across = cols / BLOCK_COLS;
        if across == 0 || rows < 2 {
            return None;
        }
        let (down, slices) = if rows >= BLOCK_ROWS {
            (rows / BLOCK_ROWS, 1)
        } else {
            // the first slice holds `rows` of the block, each later one
            // its title and `rows - 1` more
            (1, 1 + (BLOCK_ROWS - rows).div_ceil(rows - 1))
        };
        let per_page = across * down;
        Some(Layout {
            cols,
            rows,
            across,
            down,
            top: (rows - down * BLOCK_ROWS.min(rows)) / 2,
            left: (cols - across * BLOCK_COLS) / 2,
            pages: (BLOCKS * slices).div_ceil(per_page),
            slices,
        })
    }

    /// The blocks, or their slices, page `page` holds, in the card's order.
    pub fn blocks(&self, page: usize) -> impl Iterator<Item = Placed> + '_ {
        let per_page = self.across * self.down;
        let all = BLOCKS * self.slices;
        (page * per_page..((page + 1) * per_page).min(all)).map(move |s| {
            let i = s % per_page;
            Placed {
                block: s / self.slices,
                slice: s % self.slices,
                top: self.top + (i / self.across) * BLOCK_ROWS,
                left: self.left + (i % self.across) * BLOCK_COLS,
            }
        })
    }

    /// The row, from the slice's top, at which `slice` shows the block's
    /// `row`; `None` where another slice shows it.
    pub fn row(&self, slice: usize, row: usize) -> Option<usize> {
        if self.slices == 1 {
            return Some(row);
        }
        if slice == 0 {
            return (row < self.rows).then_some(row);
        }
        if row == 0 {
            return Some(0);
        }
        let start = self.rows + (slice - 1) * (self.rows - 1);
        (start..start + self.rows - 1)
            .contains(&row)
            .then(|| 1 + row - start)
    }
}

const UNSCII_WHY: &str = "vtium draws the built-in Unscii-8 in character cells under 16 pixels high. See [the issue that builds Unscii-8 into vtium](https://github.com/vtium/vtium/issues/107). With `font-size=0`, vtium takes the font's own smallest height where 16-pixel cells would leave fewer than 80×25 of them. See [the issue that sets the size `font-size=0` picks](https://github.com/vtium/vtium/issues/118). So vtium draws this display in 8×8 cells with no font keys at all. That is the most text the display holds at a size a person can still read. It costs no disk, because the built-in fonts are part of the vtium binary. Unscii-8 holds no CJK characters, no Hangul, no emoji and none of the private-use symbols, so those draw as the missing glyph, U+25A1. See [the issue about small-panel fonts that cover more](https://github.com/vtium/vtium/issues/307). In a zh, ja or ko locale, vtium draws the built-in unifont at 16 pixels instead.";

const UNIFONT_WHY: &str = "16-pixel cells leave at least 80×25 cells here, so `font-size=0` keeps its 16 pixels. See [the issue that sets the size `font-size=0` picks](https://github.com/vtium/vtium/issues/118). From 16 pixels, vtium draws the built-in unifont: 8×16 cells for Latin, Greek and Cyrillic, and 16×16 for CJK and Hangul, which it covers in full. See [the issue that builds unifont into vtium](https://github.com/vtium/vtium/issues/15). It costs no disk, because the built-in fonts are part of the vtium binary. Emoji draw as unifont's monochrome glyphs where it has one, and Nerd Font symbols draw as the missing glyph. The outline profiles draw both from the desktop font set.";

const GRAY_WHY: &str = "vtium draws a gray panel exactly as it draws a color display, and the panel's driver converts each pixel. See [the issue about 1-bit and gray displays](https://github.com/vtium/vtium/issues/135). The screens here are the color profile's drawing taken through the driver's arithmetic: a simulation of what the panel shows, not vtium's output. The font is the color profile's at this size, for the same reasons; a gray panel's few levels keep the bitmap glyphs crisp, and the card's gray bands show which levels survive the conversion.";

const ONE_BIT_WHY: &str = "A 1-bit panel lights a pixel or does not, so a bitmap font, 1-bit already, draws on it exactly: the built-in Unscii-8 at 8×8 gives the same 40×30 cells as the color profile, for the reasons that profile gives. vtium-render maps each cell's colors to lit or unlit by the cell, never by brightness, with polarity from the default background, and cuts every coverage at half. See [the issue about 1-bit and gray displays](https://github.com/vtium/vtium/issues/135). Colors show only where a cell's background differs from the default, dim draws as plain text, and the shades draw as ordered patterns.";

const DESKTOP_WHY: &str = "vtium draws an outline font only when you name a font set that lists one. This profile's vtium.conf names the desktop font set with `font-name=desktop`. The desktop font set draws text from JetBrains Mono, the private-use symbols from Symbols Nerd Font Mono and emoji from Noto Color Emoji, with the built-in unifont last for every character the others lack. vtium's font helper generates the glyphs from these fonts while vtium runs. See [the issue that generates glyphs in the font helper](https://github.com/vtium/vtium/issues/145). The font set starts at 18 points, which is 24 pixels at 96 DPI, and these profiles draw it in 24- and 32-pixel cells. Outline glyphs draw antialiased at this size. The font helper draws an emoji sequence whole, so skin tones, ZWJ sequences, flags and keycaps each draw as one emoji. Scripts that need shaping, such as Devanagari and Tamil, draw unshaped. See [the text shaping issue](https://github.com/vtium/vtium/issues/144).";

const TINY5_WHY: &str = "This profile shows the smallest font vtium ships a font set for: the example font set `tiny5`. vtium's own choice for this display is the built-in Unscii-8 at 8×8, which the profile `320x240` shows. If you want `tiny5`, you install the font set and its font by hand and name it in `font-name`. Tiny5 Mono is a pixel font whose capitals are 5 pixels tall. It draws at its own 6×9 character cell, which gives this display 53×26 cells, where the built-in Unscii-8's 8×8 gives 40×30: a third more columns, for four fewer rows. It holds ASCII, Latin-1, code page 437, Greek, Armenian, box drawing, blocks and Braille, 4,882 characters in all, so most of the card's text draws in it. vtium's sprites draw the box drawing, blocks and Braille. vtium ships the font set `tiny5` but not the font, so a machine needs Tiny5 Mono's BDF file installed by hand, as the font set's comment says. See [the Tiny5 Mono issue](https://github.com/vtium/vtium/issues/217). Its grid is shorter than one of the card's 40×30 blocks, so each block takes two screens here: its first 26 rows, then its title again and its last 4 rows. A character Tiny5 Mono lacks draws on these screens as the font's missing glyph, as CJK, Hangul and emoji do here. The console draws such a character in the built-in Unscii-8 where Unscii-8 holds it, centered in the 6×9 cell with a column cut off each side. These screens draw only the font set's own glyphs, so they do not show that. See [the issue about the fallback to the built-in font](https://github.com/vtium/vtium/issues/141).";

const TINY5_CONF: &str = "# The font set tiny5: crates/vtium-config/frits/tiny5.vtfrit in\n# /etc/vtium/fonts, with Tiny5 Mono's BDF file installed where its\n# source= line says. It draws at its own 6×9 cell.\nfont-name=tiny5\nfont-size=0\n";

const DESKTOP_CONF: &str = "# The desktop font set: tools/specimens/frits/desktop.vtfrit in\n# /etc/vtium/fonts, its glyphs generated while vtium runs.\nfont-name=desktop\nfont-size=0\n";

